#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────────
#  AutoUpload one-file installer (Fedora Linux)
#
#  Turns a long YouTube video (or podcast) into edited vertical Shorts and
#  uploads them to YouTube automatically:
#    /autoupload <youtube-url>   ->   5 published Shorts (cut, captioned, zoomed,
#                                     whooshed, scheduled 2/day by default)
#
#  This file bundles the skill code ONLY. It contains NO credentials, NO API
#  keys, NO tokens. During install you create your OWN free Google Cloud
#  credentials - see the PLACEHOLDER values below and put your real ones only
#  in your local files, never back into this script.
#
#  Run it:  bash installer-for-fedora.sh
#  What it does: installs deps (ffmpeg via RPM Fusion, yt-dlp, Python venvs),
#  unpacks the skills into ~/.claude/skills, walks you through the one-time
#  Google/YouTube authorization, and runs the doctor checks.
#  Works on Fedora Workstation / Server (needs a desktop browser for the
#  Google login step). System packages are installed with sudo.
# ─────────────────────────────────────────────────────────────────────────────
set -u

SKILLS_DIR="${AUTOUPLOAD_INSTALL_DIR:-$HOME/.claude/skills}"
CLIPPER="$SKILLS_DIR/clipper"
AUTOUP="$SKILLS_DIR/autoupload"

say() { printf '\n\033[1m== %s ==\033[0m\n' "$1"; }
step() { printf '  %s\n' "$1"; }

# base64 decoder (coreutils on Linux)
if base64 -d </dev/null >/dev/null 2>&1; then DEC="base64 -d"; else DEC="base64 -D"; fi

extract_one() {            # $1 = relative path, file content on stdin
  rel="$1"
  out="$SKILLS_DIR/$rel"
  mkdir -p "$(dirname "$out")"
  $DEC > "$out"
}

if [ "${AUTOUPLOAD_PAYLOAD_ONLY:-0}" = "1" ]; then
  echo "payload-only mode: extracting skills to $SKILLS_DIR"
fi

if [ "${AUTOUPLOAD_PAYLOAD_ONLY:-0}" != "1" ]; then
say "1/5 Installing system dependencies (dnf - will ask for your sudo password)"

# sudo or root?
SUDO=""
if [ "$(id -u)" = 0 ]; then
  SUDO=""
elif command -v sudo >/dev/null 2>&1; then
  SUDO="sudo"
else
  echo "ERROR: this script needs root to install packages (sudo not found and not root)."
  exit 1
fi

# Fedora package manager sanity check
if ! command -v dnf >/dev/null 2>&1; then
  echo "ERROR: dnf not found - this installer targets Fedora Linux."
  echo "If you are on Ubuntu/Debian, use: apt install ffmpeg yt-dlp python3-pip python3-venv"
  exit 1
fi

# ffmpeg lives in RPM Fusion, not the default Fedora repos
if ! command -v ffmpeg >/dev/null 2>&1; then
  step "enabling RPM Fusion (free + nonfree) - needed for ffmpeg on Fedora..."
  FEDORA_VER="$(rpm -E %fedora 2>/dev/null || echo 41)"
  $SUDO dnf install -y \
    "https://mirrors.rpmfusion.org/free/fedora/rpmfusion-free-release-$FEDORA_VER.noarch.rpm" \
    "https://mirrors.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$FEDORA_VER.noarch.rpm" || true
  step "installing ffmpeg + ffprobe..."
  $SUDO dnf install -y ffmpeg || { echo "ERROR: ffmpeg install failed - enable RPM Fusion manually, then rerun."; exit 1; }
else
  step "ffmpeg ok"
fi

for t in yt-dlp python3-pip; do
  if rpm -q "$t" >/dev/null 2>&1 || command -v "${t%%-*}" >/dev/null 2>&1; then
    step "$t ok"
  else
    step "installing $t ..."
    $SUDO dnf install -y "$t" || step "WARNING: '$t' install failed - the venv may cover it anyway"
  fi
done

if ! python3 -m venv --help >/dev/null 2>&1; then
  step "installing python3 venv support..."
  $SUDO dnf install -y python3-pip python3-devel || { echo "ERROR: python venv support missing"; exit 1; }
fi
fi  # end payload-only skip

# ---------------------------------------------------------------------------
# PAYLOAD (base64 blocks below this marker; the installer unpacks them)
# ---------------------------------------------------------------------------

# >>> PAYLOAD_START (generated; do not edit by hand) <<<

extract_one "clipper/SKILL.md" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/LICENSE" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/README.md" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/fonts/Montserrat-ExtraBold.ttf" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/fonts/OFL.txt" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/sfx/whoosh.wav" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/sfx/pop.wav" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/common.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/fetch.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/transcribe.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/cut.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/edit.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/check.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/make_sfx.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/doctor.sh" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "clipper/scripts/setup-mac.sh" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "autoupload/SKILL.md" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "autoupload/scripts/doctor.sh" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "autoupload/scripts/auth_setup.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

extract_one "autoupload/scripts/upload.py" <<'B64_AUTOUPLOAD_EOF'

B64_AUTOUPLOAD_EOF

# >>> PAYLOAD_END <<<

[ "${AUTOUPLOAD_PAYLOAD_ONLY:-0}" = "1" ] && { echo "payload extracted. done."; exit 0; }

say "2/5 Skills unpacked to $SKILLS_DIR"
step "clipper  (fetch / transcribe / cut / caption / edit / check)"
step "autoupload  (YouTube upload + scheduling)"

# ---------------------------------------------------------------
say "3/5 Setting up Python environments (one time, a few minutes)"

make_venv() {  # $1 = venv dir, $2... = pip packages
  V="$1"; shift
  if [ -x "$V/bin/python3" ] && "$V/bin/python3" -c 'import sys; sys.exit(0 if (3,10) <= sys.version_info[:2] else 1)' 2>/dev/null; then
    step "$V already ok"
  else
    local PYV=""
    for c in python3 python3.13 python3.12 python3.11 python3.10; do
      if command -v "$c" >/dev/null 2>&1; then PYV="$c"; break; fi
    done
    "$PYV" -m venv "$V" || { echo "ERROR: could not create venv at $V"; exit 1; }
  fi
  "$V/bin/python3" -m pip install -q --upgrade pip >/dev/null 2>&1 || true
  "$V/bin/python3" -m pip install -q certifi "$@"
  # SSL cert fix (harmless on Linux, needed if the system CA store is odd)
  SITE_DIR="$("$V/bin/python3" -c 'import site; print(site.getsitepackages()[0])')"
  cat > "$SITE_DIR/sitecustomize.py" <<'EOF'
import os
try:
    import certifi
    _b = certifi.where()
    os.environ.setdefault("SSL_CERT_FILE", _b)
    os.environ.setdefault("REQUESTS_CA_BUNDLE", _b)
except Exception:
    pass
EOF
}

step "clipper venv (speech model, video tools) - this is the big one..."
make_venv "$CLIPPER/.venv" faster-whisper "opencv-python<5" numpy Pillow yt-dlp

step "autoupload venv (YouTube API)..."
make_venv "$AUTOUP/.venv" google-api-python-client google-auth-oauthlib google-auth-httplib2

# ---------------------------------------------------------------
say "4/5 Your own YouTube credentials (NO keys are bundled in this file)"

AUTH_DONE=0
printf 'Create your Google credentials now? [Y/n] '
read -r ans
if [ "${ans:-Y}" = "Y" ] || [ "$ans" = "y" ]; then
  cat <<'STEPS'

  One-time setup (~5 minutes, free):
  1. Go to https://console.cloud.google.com/
     -> create a project named e.g.  YOUR_PROJECT_NAME
  2. APIs & Services -> Library -> search "YouTube Data API v3" -> Enable
  3. APIs & Services -> OAuth consent screen -> External
     -> app name = YOUR_APP_NAME , email = YOUR_EMAIL@example.com
     -> add YOUR_EMAIL@example.com as a test user
  4. APIs & Services -> Credentials -> Create credentials
     -> OAuth client ID -> Desktop app -> Download JSON
  5. Save that file as:
         $AUTOUP/client_secret.json
     (then come back here and press Enter)

STEPS
  while true; do
    printf 'Press Enter when client_secret.json is saved (or type s to skip): '
    read -r a2
    [ "${a2:-}" = "s" ] && break
    [ -f "$AUTOUP/client_secret.json" ] && break
    echo "  not found yet at $AUTOUP/client_secret.json"
  done
fi

if [ -f "$AUTOUP/client_secret.json" ]; then
  step "starting the one-time browser login..."
  if "$AUTOUP/.venv/bin/python3" "$AUTOUP/scripts/auth_setup.py"; then
    AUTH_DONE=1
  else
    echo "  login did not finish - you can run it later:"
    echo "    $AUTOUP/.venv/bin/python3 $AUTOUP/scripts/auth_setup.py"
  fi
else
  echo "  skipped for now. When ready, save your OAuth client JSON as:"
  echo "    $AUTOUP/client_secret.json    (PLACEHOLDER - your own file)"
  echo "  then run:"
  echo "    $AUTOUP/.venv/bin/python3 $AUTOUP/scripts/auth_setup.py"
fi

say "5/5 Doctor checks"
echo ""
echo "--- clipper doctor ---"
bash "$CLIPPER/scripts/doctor.sh" || true
echo ""
echo "--- autoupload doctor ---"
bash "$AUTOUP/scripts/doctor.sh" || true

cat <<'DONE'

────────────────────────────────────────────────────────────────
  ✅ Install finished.

  How to use (in Claude Code - restart Claude if it was open):
      /autoupload <youtube-url>
  or just:  "clip this video and upload it as Shorts"

  - clips land in  ~/Desktop/Clipper/<name>-<video-id>/clips
  - first transcription downloads a ~500 MB speech model, once
  - Short titles/captions are editable in  clips/clip-NN.txt
  - uploads schedule 2/day by default (15:00 & 22:00 slots)
  - YouTube quota: 1600 units per upload, 10000/day on a free
    project - so one 5-clip run per day; rerun the next day
  - the Google login needs a desktop browser on this machine

  Privacy: this installer contained no keys. Your credentials
  live only in  autoupload/client_secret.json  and token.json  -
  never share those two files.
────────────────────────────────────────────────────────────────
DONE

# license note: clipper is MIT (HubPost), font is SIL OFL - both bundled.
exit 0
